INSERT INTO `el_competency_report_content_package` (`id`,`product_version`,`scoring_version`,`content_version`,`template_version`,`audience`,`approval_status`,`content_approved_by`,`content_approved_at`,`psychometric_approved_by`,`psychometric_approved_at`,`question_source_sha256`,`content_source_sha256`,`effective_environment`,`disclaimer`,`create_time`,`update_time`) VALUES ('phase1-v2-content-draft','competency-frontline-phase1-v2','competency-phase1-scoring-v2','competency-phase1-content-v2','competency-phase1-report-v2','frontline_employee','draft','',NULL,'',NULL,'edb9efd27ec86bc34db3a796c2022a99495fd9ec52e8a6580cd7404b2ab933b5','329409e408f10ec7f048a757e83c963b7736f66e41e8d601ff4397fd8545b48c','','本报告基于受测者在本次胜任力测评中的作答结果生成，用于辅助了解其当前胜任力表现及发展方向。测评结果可能受到作答状态、岗位经历和测评环境等因素影响，仅供人才发展、培训与管理决策参考，不应作为招聘、晋升、淘汰或其他重大人事决定的唯一依据。使用者应结合岗位要求、工作绩效、结构化访谈及其他有效信息进行综合判断。未经授权，不得复制、传播或向无关人员披露本报告内容。',NOW(),NOW());
